import { test, expect } from '@playwright/test';

test.describe('Search Field Dropdown Matching Options', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display matching options in dropdown as user types', async ({ page }) => {
    // Locate search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Type a query to trigger dropdown
    await searchInput.fill('playwright');
    await page.waitForTimeout(100);

    // Verify dropdown is visible
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).toBeVisible();

    // Verify dropdown contains expected options
    const options = dropdown.locator('[data-testid="dropdown-option"]');
    await expect(options).toHaveCount(3);

    // Verify first option is visible
    const firstOption = options.first();
    await expect(firstOption).toBeVisible();
    await expect(firstOption).toContainText('Playwright Test Framework');

    // Verify second option is visible
    const secondOption = options.nth(1);
    await expect(secondOption).toBeVisible();
    await expect(secondOption).toContainText('Playwright API');

    // Verify third option is visible
    const thirdOption = options.nth(2);
    await expect(thirdOption).toBeVisible();
    await expect(thirdOption).toContainText('Playwright Playwright');

    // Verify dropdown is responsive to user interaction
    await firstOption.click();
    await expect(firstOption).toBeSelected();

    // Verify dropdown closes when clicking outside
    await page.click(page.locator('[data-testid="dropdown-close"]'));
    await expect(dropdown).not.toBeVisible();
  });

  test('should handle empty search input and display no results', async ({ page }) => {
    // Locate search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Clear search input
    await searchInput.fill('');
    await page.waitForTimeout(100);

    // Verify dropdown is hidden
    const dropdown = page.getByRole('listbox');
    await expect(dropdown).not.toBeVisible();

    // Verify no results message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify search input is still visible
    await expect(searchInput).toBeVisible();
  });
});
